R.append((3596476,"बादाम चिकन","एक पारंपरिक दक्षिण भारतीय पारिवारिक रेसिपी।","2",None,
["1 बड़ा चम्मच घी (या बिना नमक का मक्खन)","1 छोटा प्याज़, कद्दूकस किया हुआ","2 लहसुन की कलियाँ, कुचली या बारीक कटी हुई","2cm अदरक का टुकड़ा, कद्दूकस किया हुआ या बारीक कटा हुआ","150g गाजर, छिली और छोटे टुकड़ों में कटी हुई","1 छोटा चम्मच धनिया पाउडर","1 छोटा चम्मच जीरा पाउडर","1 चुटकी लाल मिर्च पाउडर (पसंद हो तो और डालें)","30g पिसे हुए बादाम","200g बिना हड्डी और बिना त्वचा की चिकन जाँघ या ब्रेस्ट, 2cm के टुकड़ों में कटा हुआ","120g लंबे दाने वाले या बासमती चावल","100g जमी हुई मटर","40-80ml पानी",["परोसने के लिए","2 बड़े चम्मच ताज़ा धनिया, कटा हुआ"]],
["फ्राइंग पैन में तेज़ आँच पर घी पिघलाएँ, फिर कद्दूकस किया प्याज़, लहसुन, अदरक, गाजर और मसाले डालें और 10 मिनट पकाएँ। यदि मिश्रण चिपकने लगे, तो थोड़ा पानी डालें।","पिसे हुए बादाम को 40ml पानी के साथ पैन में डालें। यदि सामग्री पैन से चिपकने लगे, तो और पानी (20-40 ml और) डालें।","चिकन के टुकड़े पैन में डालें, भूरा करें, फिर आँच मध्यम कर दें। 10 मिनट पकाएँ, ज़रूरत हो तो सॉस को पैन से चिपकने से रोकने के लिए और पानी डालें।","इस बीच, चावल को ठंडे पानी से धोएँ और पानी निथार दें। उबलते पानी के बर्तन में डालें, दोबारा उबाल आने दें, फिर आँच मध्यम कर दें, ढक्कन लगाएँ और 12 मिनट पकाएँ।","बादाम चिकन तब तैयार है जब चिकन पूरी तरह पक जाए, और सॉस गाढ़ा और रेतीले रंग का हो जाए। इस चरण पर, मटर को गरम करने के लिए डालें।","चावल परोसें, ऊपर बादाम चिकन डालें और ताज़ा कटे धनिया से सजाएँ।"],
[[CH,"यह मलाईदार, प्रामाणिक और बहुमुखी व्यंजन है जो नमक, पोटैशियम और फ़ॉस्फ़ेट में कम है।"],[CB,"इस मुख्य भोजन में चावल कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"यह व्यंजन पोटैशियम में कम है, यदि आपको पोटैशियम घटाने की सलाह दी गई है तो बताई गई मात्रा और परोसे के आकार का पालन करना सुनिश्चित करें।\nयह रेसिपी फ़ॉस्फ़ेट में कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है तो इसे इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"यह व्यंजन प्रोटीन में अधिक है और इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है, जैसे डायलिसिस ले रहे लोग। यदि आपको कम प्रोटीन खाने की सलाह दी गई है, तो चिकन की जगह 400g पानी निथारे हुए छोलों का डिब्बा उपयोग करने पर विचार करें, या चिकन की मात्रा आधी (100g) करके उसकी जगह 200g पानी निथारे हुए छोलों या मसूर का डिब्बा डालें।"],[CO,"हड्डी वाले चिकन का उपयोग करने और हड्डियाँ खुद निकालने पर विचार करें। साथ ही, लागत घटाने के लिए ताज़ी कटी धनिया की जड़ी-बूटियाँ छोड़ दें। यदि आपको पिसा जीरा या धनिया नहीं मिल पा रहा है, तो आप उनकी जगह करी पाउडर का उपयोग कर सकते हैं।"],[VT,"चिकन की जगह 400g पानी निथारी हुई मसूर या छोलों का डिब्बा डालें। वैकल्पिक रूप से 200-300g टोफ़ू का उपयोग करें।"],[VG,"चिकन की जगह 400g पानी निथारी हुई मसूर या छोलों का डिब्बा डालें। वैकल्पिक रूप से 200-300g टोफ़ू का उपयोग करें। घी की जगह वनस्पति तेल का उपयोग करें।"],[HO,"फ़ाइबर बढ़ाने के लिए सफ़ेद चावल की जगह साबुत अनाज वाले ब्राउन चावल का उपयोग करें और वसा के अधिक सेहतमंद स्रोत के लिए घी या बिना नमक के मक्खन की जगह सूरजमुखी जैसे वनस्पति तेल का उपयोग करें। हालाँकि, इससे सॉस थोड़ा पतला होगा।"],[ST,"यह करी सॉस अच्छी तरह फ़्रीज़ होता है। पकाने के तुरंत बाद ठंडा करें और तीन महीने तक फ़्रीज़ करें। दोबारा गरम करने से पहले फ्रिज में अच्छी तरह पिघलाएँ।"],[TP,"यदि आप चाहें, तो मटर और गाजर की जगह अन्य सब्ज़ियों का उपयोग किया जा सकता है। फूलगोभी और हरी फलियाँ अच्छी रहती हैं, साथ ही बैंगन और पालक भी, लेकिन इनमें पोटैशियम अधिक होता है, इसलिए यदि आपको पोटैशियम घटाना है तो इन्हें न चुनें।"]],
[]))
R.append((3643178,"बेक्ड शकरकंद पर बीन चिली",">","2",None,
["2 मध्यम शकरकंद (प्रत्येक 120g)","1 लहसुन की कली, कुचली हुई","4 हरे प्याज़, कटे हुए","400g डिब्बाबंद काली फलियाँ, धुली और पानी निथारी हुई","10g टमाटर प्यूरी","½ छोटा चम्मच मिर्च के फ़्लेक्स","1 छोटा चम्मच पिसा जीरा","½ छोटा चम्मच स्मोक्ड पैपरिका","30g जमा हुआ स्वीटकॉर्न","2 छोटे चम्मच जैतून का तेल",["परोसने के लिए","40g खट्टी क्रीम"]],
["ओवन को 200°C / फ़ैन 180°C / गैस मार्क 6 पर पहले से गरम करें। शकरकंद में चारों तरफ़ काँटे से छेद करें और थोड़ा जैतून का तेल लगाएँ। नरम होने तक लगभग 40 मिनट ओवन में बेक करें।","जब आलू पक रहे हों, तब एक बर्तन में मध्यम आँच पर जैतून का तेल गरम करें और हरे प्याज़ और लहसुन को नरम होने तक तलें।","काली फलियाँ, टमाटर प्यूरी, मिर्च के फ़्लेक्स, जीरा, पैपरिका और स्वीटकॉर्न डालें। मिलाएँ और धीमी आँच पर 10 मिनट पकाएँ।","पक जाने पर शकरकंद को ओवन से निकालें और 5 मिनट रहने दें। खुला हिस्सा बनाने के लिए, शकरकंद को लंबाई में चीरें, थोड़ा खोलें और बीन के मिश्रण से भरें। ऊपर से खट्टी क्रीम डालकर परोसें।"],
[[CH,"यह बीन चिली रेसिपी एक स्वादिष्ट शाकाहारी विकल्प है, जो भरपूर फ़ाइबर और प्रोटीन देती है।"],[CB,"इस रेसिपी में शकरकंद कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है "+INS],[PP,"बेक्ड शकरकंद और टमाटर प्यूरी जैसी कुछ उच्च पोटैशियम वाली सामग्री के उपयोग के बावजूद, सामग्री की मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। यह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से काली फलियों से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन का स्रोत है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है, जैसे डायलिसिस ले रहे लोग।"],[HO,"पोटैशियम की मात्रा को और कम करने के लिए आप भूनने से पहले शकरकंद को आधा उबाल सकते हैं।"],[ST,"बीन का मिश्रण पहले से तैयार किया जा सकता है और हवाबंद डिब्बे में फ्रिज में 3 दिन तक रखा जा सकता है।"]],
[]))
R.append((3689346,"कैरिबियाई झींगा तले चावल","जल्दी बनने वाला, आसान और बहुमुखी व्यंजन जो नमक, पोटैशियम और फ़ॉस्फ़ेट में कम है – सब्ज़ियों की जगह मटर या स्वीटकॉर्न जैसे विकल्प डालने या मिलाने के लिए स्वतंत्र महसूस करें।","4",None,
["300g लंबे दाने वाले चावल","2 छोटे चम्मच वनस्पति तेल","1 प्याज़, बारीक कटा हुआ","2 गाजर, छिली और बारीक कटी हुई","100g हरी फलियाँ, कटी हुई","1 लाल शिमला मिर्च, कटी हुई","1 बड़ा चम्मच ग्रीन सीज़निंग (या 1 छोटा चम्मच मिश्रित जड़ी-बूटियाँ)","300g कच्चे और छिले हुए किंग प्रॉन (पहले से पके हुए भी उपयोग किए जा सकते हैं)","2 अंडे, फेंटे हुए","1-2 बड़े चम्मच कम नमक वाली सोया सॉस","10g ताज़ा धनिया, कटा हुआ","4 हरे प्याज़, कटे हुए (वैकल्पिक)"],
["चावल को पैकेट के निर्देशों के अनुसार या राइस कुकर में पकाएँ। एक तरफ़ रख दें। एक कटोरे में कच्चे झींगे और ग्रीन सीज़निंग या मिश्रित जड़ी-बूटियाँ डालें, मिलाएँ और चरण 3 पूरा करते समय रहने दें (यदि पके हुए झींगे उपयोग कर रहे हैं, तो यह चरण छोड़ दें और चावल पकाते समय ग्रीन सीज़निंग या जड़ी-बूटियाँ डालें)। एक बड़े फ्राइंग पैन या कड़ाही में मध्यम आँच पर एक छोटा चम्मच तेल डालें और प्याज़, गाजर, हरी फलियाँ और शिमला मिर्च डालें, 2-5 मिनट चलाएँ और फिर सब्ज़ियाँ पकने तक ढक दें। पक जाने पर, सब्ज़ियों को कटोरे में एक तरफ़ रख दें।","उसी पैन में, एक छोटा चम्मच तेल डालें और झींगों को धीमी आँच पर पकाएँ। बार-बार पलटते हुए 5 मिनट तक पूरी तरह पकने तक तलें। पैन से निकालें और एक तरफ़ रख दें। यदि आप पके हुए झींगे उपयोग कर रहे हैं, तो आप यह चरण छोड़ सकते हैं।","सब्ज़ियों को धीमी आँच पर उसी पैन में, झींगों के रस के साथ, वापस डालें। सब्ज़ियों के बीच में जगह बनाएँ, फेंटा हुआ अंडा डालें और सब्ज़ियों के साथ भुर्जी बनाएँ।","सोया सॉस, पके झींगे और चावल डालें। मिलाएँ और व्यंजन के गरम होने तक 2 मिनट और पकाएँ। आँच तेज़ करें, धनिया डालें और मिलाएँ। चार लोगों में बाँटकर परोसें, चाहें तो कटे हरे प्याज़ डालें।"],
[[CH,"कैरिबियाई झींगा तले चावल का एक सेहतमंद रूप।"],[CB,CBRICE],[PP,"यह व्यंजन पोटैशियम में बहुत कम है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अपने आहार में पोटैशियम घटाने की सलाह दी गई है।\nयह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से अंडों और झींगों से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन का स्रोत है, इसलिए उन लोगों के लिए उपयुक्त है जिन्हें अधिक प्रोटीन खाने की सलाह दी गई है।"],[CO,"यदि कच्चे झींगे महँगे हैं, तो आप पहले से पके हुए झींगे उपयोग कर सकते हैं और ऊपर सुझाए गए चरण छोड़ सकते हैं।"],[GF,"ग्लूटेन-मुक्त सोया सॉस का उपयोग करें।"],["शाकाहारी / वीगन","झींगे छोड़ दें और उनकी जगह स्मोक्ड टोफ़ू डालें।"],[HO,"यह रेसिपी नमक में कम है क्योंकि कम नमक वाली सोया सॉस का उपयोग किया गया है। हालाँकि, यह फिर भी उच्च नमक वाला उत्पाद है, इसलिए अतिरिक्त नमक से बचने के लिए इस सामग्री को सावधानी से मापना सबसे अच्छा है।"],[ST,"इस व्यंजन को ताज़ा बना हुआ खाना सबसे अच्छा रहता है क्योंकि चावल को दोबारा गरम करने की सलाह नहीं दी जाती, विशेष रूप से यदि आपका किडनी प्रत्यारोपण हुआ है।"]],
[]))
